import React from 'react';
import Button from '../Button';
import Tag from '../Tag';
import { Card, Descricao, Titulo, Infos, Imagem, TituloContainer, NotaContainer } from './styles';
import { FaStar } from 'react-icons/fa'; // Importe um ícone (exemplo: estrela)

type Props = {
  title: string;
  description: string;
  infos: string[];
  image: string;
  nota: number; // Adicionado nota como number
};

const Product = ({ description, image, infos, title, nota }: Props) => (
  <Card>
    <Imagem src={image} alt={title} />
    {infos && infos.length > 0 && (
      <Infos>
        {infos.map((info) => (
          <Tag key={info}>{info}</Tag>
        ))}
      </Infos>
    )}
    <Descricao>
      <TituloContainer>
        <Titulo>{title}</Titulo>
        <NotaContainer>
          <span>{nota}</span>
          <FaStar /> {/* Ícone ao lado da nota */}
        </NotaContainer>
      </TituloContainer>
      <p>{description}</p>
      <Button
        type="button"
        title="Saiba mais"
        onClick={() => console.log('Navegar para detalhes')}
      >
        Saiba mais
      </Button>
    </Descricao>
  </Card>
);

export default Product;
